'use strict';
const $ = selector => document.querySelector(selector);
const uid = prefix => `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
const now = () => new Date().toISOString();
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
function emptyWorkspace() {
  return { version: 1, revision: 0, updatedAt: now(), projects: [], tasks: [], databank: [], documentation: [], people: [], activity: [] };
}
let state = emptyWorkspace(), sha = null, user = '', view = 'home', selectedProjectId = null, selectedTaskId = null, saveTimer, bridgePollTimer, bridgeSyncPromise, availableServers = [], projectServerShas = new Map();
const statuses = ['Created','Assigned','In Progress','Submitted','Under Review','Approved','Completed','Waiting for information','Waiting for external response','Blocked','Changes requested','On hold','Cancelled','Archived'];
const githubMatchAttempts = new Set(), githubMatchInFlight = new Set();
const demoIds = new Set(['project-orbit','project-atlas','task-delivery','task-partners','record-delivery','event-1','event-2']);

function cleanWorkspace(workspace) {
  const clean = workspace && typeof workspace === 'object' ? workspace : emptyWorkspace();
  let removed = false;
  for (const collection of ['projects','tasks','databank','documentation','people','activity']) {
    if (!Array.isArray(clean[collection])) clean[collection] = [];
    const filtered = clean[collection].filter(record => !demoIds.has(record?.id));
    removed ||= filtered.length !== clean[collection].length;
    clean[collection] = filtered;
  }
  return { workspace: clean, removed };
}

function meta(record, creating = false) { const stamp = now(); if (creating) Object.assign(record,{createdAt:stamp,createdBy:user,revision:0}); Object.assign(record,{updatedAt:stamp,updatedBy:user,revision:(record.revision||0)+1}); state.revision++; state.updatedAt=stamp; }
function activity(type,title,detail,entityId){state.activity.unshift({id:uid('event'),type,title,detail,entityId,actor:user,createdAt:now()});state.activity=state.activity.slice(0,100)}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600)}
function syncStatus(type,text){const el=$('#sync');el.className=`sync ${type}`;el.innerHTML=`<i></i>${text}`}
function queueSave(summary='update workspace'){syncStatus('saving','SAVING');clearTimeout(saveTimer);saveTimer=setTimeout(()=>save(summary),650)}
async function save(summary){try{for(const project of state.projects.filter(p=>p.server)){if(project.serverAccess===false)continue;const data={project:{...project,serverAccess:undefined},tasks:state.tasks.filter(t=>t.projectId===project.id),databank:state.databank.filter(r=>r.projectId===project.id)};const saved=await window.crowdnet.writeProjectServer({server:project.server,projectId:project.id,data,sha:projectServerShas.get(project.id)});if(saved.conflict)throw new Error(`${project.name} server changed remotely. Restore before saving.`);projectServerShas.set(project.id,saved.sha)}const custom=new Set(state.projects.filter(p=>p.server).map(p=>p.id)),base={...state,projects:state.projects.map(p=>p.server?{id:p.id,name:p.name,server:p.server,accent:p.accent,status:p.status,createdAt:p.createdAt,createdBy:p.createdBy,updatedAt:p.updatedAt,updatedBy:p.updatedBy,revision:p.revision}:p),tasks:state.tasks.filter(t=>!custom.has(t.projectId)),databank:state.databank.filter(r=>!custom.has(r.projectId))};const result=await window.crowdnet.save({workspace:base,sha,summary});if(result.conflict){syncStatus('conflict','CONFLICT');toast('Primary server changed remotely. Restore before saving again.');return}sha=result.sha;syncStatus('saved','SAVED')}catch(error){syncStatus('conflict','RETRY REQUIRED');toast(error.message)}}
async function hydrateProjectServers(){projectServerShas.clear();for(const shell of state.projects.filter(p=>p.server)){try{const result=await window.crowdnet.readProjectServer({server:shell.server,projectId:shell.id}),data=result.data||{};Object.assign(shell,data.project||{}, {server:shell.server,serverAccess:true});state.tasks=state.tasks.filter(t=>t.projectId!==shell.id).concat(data.tasks||[]);state.databank=state.databank.filter(r=>r.projectId!==shell.id).concat(data.databank||[]);projectServerShas.set(shell.id,result.sha)}catch(error){shell.serverAccess=false;shell.serverError=error.status===404?'Project workspace has not been initialized on this server.':'Your access key does not include this server.'}}}

async function restore(){syncStatus('saving','RESTORING');try{const result=await window.crowdnet.restore();const cleaned=cleanWorkspace(result.workspace||state);state=cleaned.workspace;sha=result.sha;await hydrateProjectServers();reconcileCompletedTasks();if(result.source==='bridge')await syncBridgeIssues();render();syncStatus(result.source==='cache'?'conflict':'saved',result.source==='cache'?'OFFLINE CACHE':'SAVED');if(cleaned.removed&&result.source==='bridge')queueSave('remove legacy demo records');toast(cleaned.removed?'Legacy placeholder records removed.':result.source==='cache'?'Server unavailable — local cache restored.':'Workspace and server tasks restored.')}catch(error){syncStatus('conflict','SERVER UNAVAILABLE');toast(error.message)}}

const LOGIN_USERNAME = 'unclesam45';
const logger = $('#crowdnet-connection-logger');
function updateLoginFields({server,accessKey}={}){for(const form of [$('#login'),$('#loggerLogin')]){if(server!==undefined)form.elements.server.value=String(server??'');if(accessKey!==undefined)form.elements.accessKey.value=String(accessKey??'')}}
async function connect({server,accessKey,remember=false},output){
  $('#loginMessage').textContent='';$('#loggerMessage').textContent='';output.textContent='VERIFYING PRIVATE SERVER…';
  try{const result=await window.crowdnet.authenticate({username:LOGIN_USERNAME,server,accessKey,remember});user=result.username;logger.classList.add('connected');output.textContent='CONNECTION CONFIRMED';try{availableServers=(await window.crowdnet.listServers()).servers||[]}catch{availableServers=[]}await new Promise(resolve=>setTimeout(resolve,650));$('#auth').classList.add('hidden');$('#loader').classList.remove('hidden');setTimeout(()=>$('#loadStep').textContent='Restoring workspace and server tasks…',400);const loaded=await window.crowdnet.restore();const cleaned=cleanWorkspace(loaded.workspace||state);state=cleaned.workspace;sha=loaded.sha;await hydrateProjectServers();reconcileCompletedTasks();if(loaded.source==='bridge')await syncBridgeIssues();startBridgeIssuePolling();setTimeout(()=>{$('#loader').classList.add('hidden');$('#app').classList.remove('hidden');$('#currentUser').textContent=user.toUpperCase();$('#avatar').textContent=user[0].toUpperCase();render();if(cleaned.removed&&loaded.source==='bridge')queueSave('remove legacy demo records')},750)}catch(error){logger.classList.remove('connected');output.textContent=error.message}
}
$('#login').addEventListener('submit',event=>{event.preventDefault();connect({server:$('#server').value,accessKey:$('#accessKey').value,remember:$('#remember').checked},$('#loginMessage'))});
const loggerLogin=$('#loggerLogin');
loggerLogin.addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;updateLoginFields({server:form.elements.server.value,accessKey:form.elements.accessKey.value});connect({server:form.elements.server.value,accessKey:form.elements.accessKey.value,remember:$('#remember').checked},$('#loggerMessage'))});
loggerLogin.addEventListener('keydown',event=>{if(event.key!=='Enter'||event.isComposing||event.repeat||event.altKey||event.ctrlKey||event.metaKey||event.shiftKey||!event.target.matches('input'))return;event.preventDefault();loggerLogin.requestSubmit()});
window.crowdnetLogger=Object.freeze({element:logger,update:updateLoginFields,clear:()=>updateLoginFields({server:'',accessKey:''})});
window.addEventListener('crowdnet:logger-update',event=>updateLoginFields(event.detail));
window.crowdnet.loadCredentials().then(saved=>{if(saved){updateLoginFields(saved);$('#remember').checked=true}});
$('#restore').onclick=restore; $('#newProject').onclick=projectDialog;
$('#nav').onclick=event=>{const button=event.target.closest('button[data-view]');if(!button)return;view=button.dataset.view;selectedProjectId=null;selectedTaskId=null;document.querySelectorAll('#nav button').forEach(x=>x.classList.toggle('active',x===button));render()};

function render(){const names={home:'COMMAND CENTER',board:'VISUAL BOARD',projects:'PROJECT NETWORK',tasks:'TASK OPERATIONS',databank:'OPERATIONAL MEMORY',info:'DOCUMENTATION LIBRARY',people:'RESPONSIBILITY NETWORK'},project=state.projects.find(p=>p.id===selectedProjectId),task=state.tasks.find(t=>t.id===selectedTaskId);if(selectedProjectId&&!project)selectedProjectId=null;if(selectedTaskId&&!task)selectedTaskId=null;const detail=task||project;$('#breadcrumb').textContent=task?`CROWDNET / TASKS / ${task.title.toUpperCase()}`:project?`CROWDNET / PROJECTS / ${project.name.toUpperCase()}`:`CROWDNET / ${names[view]}`;$('#viewTitle').textContent=detail?detail.name||detail.title:view==='home'?`Good evening, ${user}.`:names[view].replace(/\b\w/g,c=>c.toUpperCase());$('#content').innerHTML=task?taskDetailView(task):project?projectView(project):({home:homeView,board:boardView,projects:projectsView,tasks:tasksView,databank:databankView,info:infoView,people:peopleView})[view]();bindContent()}
const statusClass=s=>s.toLowerCase().replaceAll(' ','-');
function taskGlowClass(status){if(['Completed','Approved'].includes(status))return 'task-glow glow-complete';if(['Assigned','In Progress','Submitted','Under Review','Changes requested'].includes(status))return 'task-glow glow-progress';return 'task-glow glow-standby'}
function homeView(){const blockers=state.tasks.filter(t=>t.status==='Blocked').length, review=state.tasks.filter(t=>['Submitted','Under Review'].includes(t.status)).length;return `<div class="metrics"><div class="metric"><b>${state.projects.length}</b><span>ACTIVE PROJECTS</span></div><div class="metric"><b>${state.tasks.filter(t=>!['Completed','Archived'].includes(t.status)).length}</b><span>OPEN TASKS</span></div><div class="metric"><b>${review}</b><span>WAITING REVIEW</span></div><div class="metric"><b>${blockers}</b><span>ACTIVE BLOCKERS</span></div></div><div class="hero-grid"><section class="panel"><div class="panel-title"><h3>LIVE BUSINESS TIMELINE</h3><small>${state.activity.length} events</small></div><div class="timeline">${state.activity.slice(0,12).map(event=>`<article class="event"><span class="event-icon">${event.type==='project'?'◇':'▣'}</span><div><strong>${esc(event.title)}</strong><p>${esc(event.detail)} · ${esc(event.actor)}</p></div><time>${new Date(event.createdAt).toLocaleDateString()}</time></article>`).join('')||'<div class="empty">No activity yet.</div>'}</div></section><section class="panel"><div class="panel-title"><h3>CURRENT PRIORITIES</h3></div>${state.projects.slice(0,3).map(project=>projectCard(project)).join('')}<div class="panel-title" style="margin-top:28px"><h3>ASSIGNED TO YOU</h3></div>${state.tasks.filter(t=>t.assignee.toLowerCase()===user.toLowerCase()).slice(0,4).map(taskRow).join('')||'<p class="empty">No assigned work.</p>'}</section></div>`}
function projectServer(project, compact=false){const primary=!project?.server,locked=!primary&&project.serverAccess===false,label=primary?'CROWDNET PRIMARY':project.server.split('/').pop();return `<div class="server-indicator ${locked?'restricted':'connected'} ${compact?'compact':''}" title="${esc(locked?'Access unavailable':`Connected to ${label}`)}"><span class="server-core"><i></i><b></b></span><span class="server-copy"><small>${locked?'SERVER RESTRICTED':primary?'PRIMARY SERVER':'PROJECT SERVER'}</small><strong>${esc(label)}</strong></span><em>${locked?'LOCKED':'LIVE'}</em></div>`}
function projectCard(p){return `<article class="project-card" data-project="${p.id}" style="--accent:${p.accent}"><div class="project-card-grid"></div>${projectServer(p,true)}<div class="project-top"><div><span class="mono">${esc(p.stage)} / ${esc(p.priority)}</span><h3>${esc(p.name)}</h3></div><div class="card-actions"><span class="tag">${esc(p.status)}</span><button class="ghost" data-edit-project="${p.id}" aria-label="Edit ${esc(p.name)}">EDIT</button><button class="danger-button" data-delete-project="${p.id}" aria-label="Delete ${esc(p.name)}">DELETE</button></div></div><p>${esc(p.description)}</p><div class="progress"><i style="width:${p.progress}%"></i></div><p>${p.progress}% · NEXT: ${esc(p.nextAction)}</p></article>`}
function projectsView(){return `<div class="panel-title"><h3>PRIORITY ORDER · ${state.projects.length} PROJECTS</h3><small>Drag order is synchronized through the Bridge</small></div><div class="project-list">${state.projects.map(projectCard).join('')||'<div class="empty">No projects yet. Create the first project to begin.</div>'}</div>`}
function projectView(project){
  if(project.server&&project.serverAccess===false)return accessDeniedView(project);
  const tasks=state.tasks.filter(t=>t.projectId===project.id),completed=tasks.filter(t=>['Completed','Approved'].includes(t.status)),active=tasks.filter(t=>!['Completed','Approved'].includes(t.status)),topTask=active[0],inProgress=active.filter(t=>['Assigned','In Progress','Submitted','Under Review','Changes requested'].includes(t.status)).length,blocked=active.filter(t=>t.status==='Blocked').length,percent=tasks.length?Math.round(completed.length/tasks.length*100):Number(project.progress||0),taskIds=new Set(tasks.map(t=>t.id)),events=state.activity.filter(e=>e.entityId===project.id||taskIds.has(e.entityId)).slice(0,8);
  return `<div class="project-dashboard" style="--accent:${project.accent||'#8b62ff'}"><button class="back-link" id="backProjects">← ALL PROJECTS</button><div class="project-command-bar"><div><span>PROJECT CONTROL</span><strong>LIVE OPERATIONAL WORKSPACE</strong></div>${projectServer(project)}</div><section class="project-hero"><div class="project-hero-copy"><div class="project-eyebrow"><span class="status active">${esc(project.status||'Active')}</span><span>${esc(project.stage)} PHASE</span><span>${esc(project.priority)} PRIORITY</span></div><h1>${esc(project.name)}</h1><p>${esc(project.description||'No project brief has been added yet.')}</p><div class="project-hero-actions"><button class="primary" id="projectNewTask">＋ ADD TASK</button><button class="ghost" data-edit-project="${project.id}">EDIT PROJECT</button><button class="ghost github-sync" id="syncGithub" ${githubMatchInFlight.has(project.id)?'disabled':''}>◉ ${githubMatchInFlight.has(project.id)?'MATCHING…':'SYNC SOURCE'}</button></div>${project.githubRepository?`<p class="github-match"><i></i> MATCHED TO ${esc(project.githubRepository)} · ${project.githubSyncedAt?new Date(project.githubSyncedAt).toLocaleString():'READY'}</p>`:''}</div><div class="progress-orbit" style="--progress:${percent*3.6}deg"><div><strong>${percent}%</strong><span>COMPLETE</span></div></div></section><div class="project-metrics"><article><span>✓</span><div><b>${completed.length}</b><small>COMPLETED</small></div></article><article><span>↗</span><div><b>${inProgress}</b><small>IN PROGRESS</small></div></article><article><span>▣</span><div><b>${active.length}</b><small>REMAINING</small></div></article><article class="${blocked?'has-blockers':''}"><span>!</span><div><b>${blocked}</b><small>BLOCKERS</small></div></article></div>${topTask?`<section class="now-task ${taskGlowClass(topTask.status)}" data-task="${topTask.id}"><div class="now-signal"><i></i><span>DO THIS NOW</span></div><div><small>TOP TASK · ${esc(topTask.priority||'MEDIUM')} PRIORITY</small><h2>${esc(topTask.title)}</h2><p>${esc(topTask.objective||'Open the task to review its objective and begin work.')}</p></div><span class="status ${statusClass(topTask.status)}">${esc(topTask.status)}</span><b>OPEN TASK →</b></section>`:`<section class="now-task all-clear"><div class="now-signal"><i></i><span>ALL CLEAR</span></div><div><small>EXECUTION COMPLETE</small><h2>No active tasks remain</h2><p>Every task attached to this project has been completed.</p></div><b>✓ COMPLETE</b></section>`}<div class="project-columns"><section class="project-work-stack"><section class="panel project-work"><div class="panel-title"><div><p class="mono">ACTIVE EXECUTION PLAN</p><h3>WHAT STILL NEEDS TO BE DONE</h3></div><small>DRAG TO REORDER · ${active.length} ACTIVE</small></div><div class="project-task-list" id="projectTasks">${active.map((t,index)=>projectTaskRow(t,index,true)).join('')||'<div class="empty compact-list-empty">No active tasks. This project is clear.</div>'}</div></section><section class="panel project-work completed-work"><div class="panel-title"><div><p class="mono">COMPLETED WORK</p><h3>FINISHED TASKS</h3></div><small>${completed.length} COMPLETE</small></div><div class="project-task-list">${completed.map((t,index)=>projectTaskRow(t,index,false)).join('')||'<div class="empty compact-list-empty">No completed tasks yet.</div>'}</div></section></section><div class="project-rail"><section class="panel objective-card"><p class="mono">CURRENT OBJECTIVE</p><h3>${esc(project.objective||'Define the next measurable outcome')}</h3><div class="next-action"><small>NEXT ACTION</small><p>${esc(topTask?.title||project.nextAction||'All tasks are complete.')}</p></div></section><section class="panel"><div class="panel-title"><h3>RECENT ACTIVITY</h3><small>LIVE</small></div><div class="project-activity">${events.map(event=>`<article><i></i><div><strong>${esc(event.title)}</strong><p>${esc(event.detail)}</p><time>${new Date(event.createdAt).toLocaleDateString(undefined,{month:'short',day:'numeric'})} · ${esc(event.actor||'System')}</time></div></article>`).join('')||'<div class="empty">No project activity yet.</div>'}</div></section></div></div></div>`}
function projectTaskRow(t,index,draggable=true){return `<article class="project-task ${taskGlowClass(t.status)} ${draggable?'active-task':'completed-task'}" ${draggable?'draggable="true"':''} data-task="${t.id}"><span class="drag" title="${draggable?'Drag to reorder':'Completed'}">${draggable?'⠿':'✓'}</span><span class="task-index">${String(index+1).padStart(2,'0')}</span><div class="task-copy"><strong>${esc(t.title)}</strong><p>${esc(t.objective||'No objective specified')} · ${esc(t.assignee)}</p></div><span class="task-priority">${esc(t.priority||'Medium')}</span><span class="status ${statusClass(t.status)}">${esc(t.status)}</span><button class="task-more" data-edit-task="${t.id}" aria-label="Edit ${esc(t.title)}">•••</button></article>`}
function taskRow(t,index=0,completed=false,draggable=false){const project=state.projects.find(p=>p.id===t.projectId);return `<article class="task operation-task ${taskGlowClass(t.status)} ${completed?'is-completed':'is-active'}" data-task="${t.id}" ${draggable?'draggable="true"':''}><span class="operation-index">${completed?'✓':draggable?'⠿ '+String(index+1).padStart(2,'0'):String(index+1).padStart(2,'0')}</span><div class="operation-copy"><div><strong>${esc(t.title)}</strong>${t.githubRef?'<span class="github-task-badge">SOURCE</span>':''}</div><p>${esc(project?.name||'No project')} · ${esc(t.assignee||'Unassigned')}</p></div><span class="task-priority">${esc(t.priority||'Medium')}</span><div class="card-actions"><span class="status ${statusClass(t.status)}">${esc(t.status)}</span><button class="task-more" data-edit-task="${t.id}" aria-label="Edit ${esc(t.title)}">•••</button><button class="danger-button" data-delete-task="${t.id}" aria-label="Delete ${esc(t.title)}">DELETE</button></div></article>`}
function ensureDatabankRecord(task){if(task.status!=='Completed')return null;let record=state.databank.find(item=>item.taskId===task.id);if(record)return record;record={id:uid('record'),title:task.title,answer:task.finalResult||task.objective||`Completed task: ${task.title}`,projectId:task.projectId,taskId:task.id,completedBy:task.assignee,approvedBy:user||task.creator||'System',completionDate:task.githubClosedAt||now(),keywords:task.title.toLowerCase().split(/\W+/).filter(x=>x.length>3),category:task.githubIssueNumber?'Server issue':task.githubRef?'GitHub pull request':'Task result',reliability:'Confirmed',sourceUrl:task.githubUrl||''};meta(record,true);state.databank.unshift(record);activity('databank',`${task.title} preserved`,'Completed task converted into confirmed knowledge',record.id);return record}
function reconcileCompletedTasks(){let added=0;state.tasks.filter(task=>task.status==='Completed').forEach(task=>{if(!state.databank.some(record=>record.taskId===task.id)){ensureDatabankRecord(task);added++}});if(added)queueSave('backfill completed task knowledge')}
function bridgeIssueBody(task){return `${task.objective||''}\n\n${task.instructions||''}\n\n<!-- crowdnet-task ${JSON.stringify({taskId:task.id,projectId:task.projectId||''})} -->`.trim()}
function bridgeMetadata(body){const match=String(body||'').match(/<!-- crowdnet-task (\{.*?\}) -->/);try{return match?JSON.parse(match[1]):{}}catch{return {}}}
function applyIssue(task,issue){const before=JSON.stringify([task.title,task.status,task.githubIssueState,task.githubSyncedAt,task.githubClosedAt]);task.githubIssueNumber=issue.number;task.githubRef=`UNCLESAM45/CROWDNET_MANAGER_BRIDGE#${issue.number}`;task.githubUrl=issue.url;task.githubIssueState=issue.state;task.githubSyncedAt=issue.updatedAt;if(issue.state==='closed'){task.status='Completed';task.githubClosedAt=issue.closedAt;ensureDatabankRecord(task)}else if(task.status==='Completed'&&JSON.parse(before)[2]==='closed'){task.status='Created';task.githubClosedAt=null;state.databank=state.databank.filter(record=>record.taskId!==task.id)}return before!==JSON.stringify([task.title,task.status,task.githubIssueState,task.githubSyncedAt,task.githubClosedAt])}
async function createIssueForTask(task){const issue=await window.crowdnet.createBridgeIssue({server:state.projects.find(p=>p.id===task.projectId)?.server,title:task.title,body:bridgeIssueBody(task)});applyIssue(task,issue);return issue}
async function updateIssueForTask(task){const completed=['Completed','Approved'].includes(task.status);if(!task.githubIssueNumber){await createIssueForTask(task);if(!completed)return; }const issue=await window.crowdnet.updateBridgeIssue({server:state.projects.find(p=>p.id===task.projectId)?.server,number:task.githubIssueNumber,title:task.title,body:bridgeIssueBody(task),state:completed?'closed':'open'});applyIssue(task,issue);return issue}
async function performBridgeIssueSync(){const servers=[null,...state.projects.filter(p=>p.server&&p.serverAccess!==false).map(p=>p.server)].filter((v,i,a)=>a.indexOf(v)===i),results=await Promise.all(servers.map(server=>window.crowdnet.listBridgeIssues({server}))),result={repository:'project servers',issues:results.flatMap(r=>r.issues.map(issue=>({...issue,server:r.repository})))},byNumber=new Map(state.tasks.filter(task=>task.githubIssueNumber).map(task=>[`${state.projects.find(p=>p.id===task.projectId)?.server||'UNCLESAM45/CROWDNET_MANAGER_BRIDGE'}#${Number(task.githubIssueNumber)}`,task]));let changed=0;for(const issue of result.issues){let task=byNumber.get(`${issue.server}#${issue.number}`);if(!task){const metadata=bridgeMetadata(issue.body);task=state.tasks.find(item=>item.id===metadata.taskId);if(!task){task={id:metadata.taskId||uid('task'),projectId:metadata.projectId||'',title:issue.title,assignee:issue.author,status:issue.state==='closed'?'Completed':'Created',priority:'Medium',objective:String(issue.body||'').replace(/<!-- crowdnet-task .*? -->/s,'').trim(),instructions:'',notes:'',draftAnswer:'',finalResult:issue.state==='closed'?`Completed through server issue #${issue.number}`:'',reviewComments:'',creator:'GitHub Bridge'};meta(task,true);task.createdAt=issue.createdAt||task.createdAt;state.tasks.push(task)}changed++}if(task.title!==issue.title){task.title=issue.title;changed++}if(applyIssue(task,issue))changed++;byNumber.set(`${issue.server}#${issue.number}`,task)}for(const task of state.tasks.filter(item=>state.projects.find(p=>p.id===item.projectId)?.serverAccess!==false&&!['Completed','Approved','Archived','Cancelled'].includes(item.status)&&!item.githubIssueNumber)){await createIssueForTask(task);changed++}if(changed){state.revision++;state.updatedAt=now();activity('github','Server tasks synchronized',`${changed} change${changed===1?'':'s'} reconciled across connected servers`,'bridge');queueSave('sync Bridge issues')}return changed}
async function syncBridgeIssues(){if(!bridgeSyncPromise)bridgeSyncPromise=performBridgeIssueSync().finally(()=>{bridgeSyncPromise=null});return bridgeSyncPromise}
function startBridgeIssuePolling(){clearInterval(bridgePollTimer);bridgePollTimer=setInterval(async()=>{if(document.hidden||!user)return;try{if(await syncBridgeIssues())render()}catch(error){syncStatus('conflict','ISSUE SYNC RETRY');console.warn('[CrowdNet] Bridge issue polling failed:',error.message)}},15000)}
async function autoMatchProject(project, manual=false){if(githubMatchInFlight.has(project.id)||(!manual&&githubMatchAttempts.has(project.id)))return;githubMatchAttempts.add(project.id);githubMatchInFlight.add(project.id);if(manual)render();try{const result=await window.crowdnet.matchCompletedPullRequests(project.name);if(!result.matched){if(manual)toast(`No accessible GitHub repository named “${project.name}” was found.`);return}const known=new Set(state.tasks.map(task=>task.githubRef).filter(Boolean));let imported=0;for(const pull of result.pullRequests){const githubRef=`${result.repository.fullName}#${pull.number}`;if(known.has(githubRef))continue;const task={id:uid('task'),projectId:project.id,title:pull.title,assignee:pull.author,status:'Completed',priority:'Medium',objective:`Completed through GitHub pull request #${pull.number}`,instructions:`Imported automatically from ${pull.url}`,notes:pull.body,draftAnswer:'',finalResult:`Closed pull request #${pull.number}: ${pull.title}`,reviewComments:'',creator:'GitHub Auto Match',githubRef,githubUrl:pull.url,githubClosedAt:pull.closedAt,githubMergedAt:pull.mergedAt};meta(task,true);task.createdAt=pull.createdAt||task.createdAt;state.tasks.push(task);ensureDatabankRecord(task);known.add(githubRef);imported++}project.githubRepository=result.repository.fullName;project.githubRepositoryUrl=result.repository.url;project.githubSyncedAt=now();meta(project);activity('github',`${result.repository.fullName} synchronized`,`${imported} completed task${imported===1?'':'s'} imported from closed pull requests`,project.id);queueSave('sync completed GitHub pull requests');toast(imported?`${imported} completed GitHub task${imported===1?'':'s'} imported.`:'GitHub is already up to date.')}catch(error){toast(`GitHub matching failed: ${error.message}`)}finally{githubMatchInFlight.delete(project.id);if(selectedProjectId===project.id)render()}}
function taskDetailView(task){const project=state.projects.find(p=>p.id===task.projectId),flow=['Created','Assigned','In Progress','Submitted','Under Review','Completed'],normalized=task.status==='Approved'?'Completed':task.status,current=Math.max(0,flow.indexOf(normalized)),next=current<flow.length-1?flow[current+1]:null,events=state.activity.filter(e=>e.entityId===task.id).slice(0,8),isDone=['Completed','Approved'].includes(task.status);return `<div class="task-dashboard ${taskGlowClass(task.status)}" data-task="${task.id}"><button class="back-link" id="backTasks">← ${selectedProjectId?'PROJECT OVERVIEW':'ALL TASKS'}</button><section class="task-hero"><div>${projectServer(project,true)}<div class="project-eyebrow"><span class="status ${statusClass(task.status)}">${esc(task.status)}</span><span>${esc(task.priority||'Medium')} PRIORITY</span><span>${esc(project?.name||'NO PROJECT')}</span></div><h1>${esc(task.title)}</h1><p>${esc(task.objective||'No objective has been defined for this task.')}</p><div class="project-hero-actions"><button class="primary" id="advanceTask" ${!next?'disabled':''}>${next?`MARK AS ${esc(next.toUpperCase())}`:'✓ TASK COMPLETE'}</button><button class="ghost" data-edit-task="${task.id}">EDIT TASK</button></div></div><div class="task-owner"><span>${esc((task.assignee||'?')[0].toUpperCase())}</span><small>RESPONSIBLE OWNER</small><strong>${esc(task.assignee||'Unassigned')}</strong><p>Updated ${new Date(task.updatedAt||task.createdAt||Date.now()).toLocaleDateString()}</p></div></section><section class="workflow-card"><div class="workflow-head"><div><p class="mono">COMPLETION PATH</p><h3>FROM ASSIGNMENT TO APPROVAL</h3></div><strong>${current+1} / ${flow.length}</strong></div><div class="workflow">${flow.map((step,index)=>`<div class="workflow-step ${index<current?'done':index===current?'current':''}"><i>${index<current?'✓':String(index+1).padStart(2,'0')}</i><span>${step}</span></div>`).join('')}</div></section><div class="task-columns"><main><section class="panel task-brief"><div class="panel-title"><div><p class="mono">TASK BRIEF</p><h3>WHAT NEEDS TO HAPPEN</h3></div></div><div class="brief-block"><small>OBJECTIVE</small><p>${esc(task.objective||'No objective provided.')}</p></div><div class="brief-block"><small>INSTRUCTIONS</small><p>${esc(task.instructions||'No additional instructions provided.')}</p></div></section><section class="panel task-output"><div class="panel-title"><div><p class="mono">DELIVERY WORKSPACE</p><h3>${isDone?'CONFIRMED RESULT':'WORK IN PROGRESS'}</h3></div><button class="ghost" data-edit-task="${task.id}">UPDATE WORK</button></div><div class="output-grid"><div><small>NOTES & RESEARCH</small><p>${esc(task.notes||'No research notes have been added yet.')}</p></div><div><small>DRAFT ANSWER</small><p>${esc(task.draftAnswer||'No draft has been prepared yet.')}</p></div><div class="final-output"><small>FINAL CONFIRMED RESULT</small><p>${esc(task.finalResult||'The final deliverable will appear here once confirmed.')}</p></div></div></section></main><aside class="task-rail"><section class="panel task-details"><p class="mono">TASK DETAILS</p><dl><div><dt>PROJECT</dt><dd>${esc(project?.name||'None')}</dd></div><div><dt>CREATED BY</dt><dd>${esc(task.creator||task.createdBy||'Unknown')}</dd></div><div><dt>ASSIGNEE</dt><dd>${esc(task.assignee||'Unassigned')}</dd></div><div><dt>PRIORITY</dt><dd>${esc(task.priority||'Medium')}</dd></div></dl></section><section class="panel"><div class="panel-title"><h3>RECENT ACTIVITY</h3><small>LIVE</small></div><div class="project-activity">${events.map(event=>`<article><i></i><div><strong>${esc(event.title)}</strong><p>${esc(event.detail)}</p><time>${new Date(event.createdAt).toLocaleDateString(undefined,{month:'short',day:'numeric'})} · ${esc(event.actor||'System')}</time></div></article>`).join('')||'<div class="empty compact-empty">No task activity yet.</div>'}</div></section>${task.reviewComments?`<section class="panel review-card"><p class="mono">REVIEW COMMENTS</p><p>${esc(task.reviewComments)}</p></section>`:''}</aside></div></div>`}
async function advanceSelectedTask(){const task=state.tasks.find(t=>t.id===selectedTaskId),flow=['Created','Assigned','In Progress','Submitted','Under Review','Completed'];if(!task)return;const current=Math.max(0,flow.indexOf(task.status==='Approved'?'Completed':task.status)),next=flow[current+1];if(!next)return;const old=task.status;task.status=next;try{await updateIssueForTask(task)}catch(error){task.status=old;toast(`Bridge issue update failed: ${error.message}`);return}meta(task);ensureDatabankRecord(task);activity('status',`${task.title}: ${next}`,`${old} → ${next}`,task.id);render();queueSave('advance task status and Bridge issue');toast(`Task moved to ${next}`)}
function personColor(name){state.personColors ||= {};if(!state.personColors[name]){let hash=0;for(const char of String(name))hash=(hash*31+char.charCodeAt(0))%360;state.personColors[name]=`hsl(${hash} 82% 68%)`}return state.personColors[name]}
function accessDeniedView(project){return `<section class="access-denied"><div class="access-radar"><i></i><b>LOCKED</b></div><p class="mono">SERVER ACCESS / RESTRICTED</p><h1>${esc(project.name)}</h1><p>This project is visible to the network, but its workspace lives on a server that is not included in your access key.</p><div class="server-capsule"><span>PRIVATE SERVER</span><strong>${esc(project.server?.split('/').pop()||'Unavailable')}</strong></div>${projectServer(project)}<button class="ghost" id="backProjects">← RETURN TO PROJECTS</button></section>`}
function boardView(){const people=[...new Set(state.tasks.map(t=>t.assignee||'Unassigned'))];return `<div class="board-shell"><div class="board-heading"><div><p class="mono">CROWDNET / CONNECTED EXECUTION</p><h1>The Board.</h1><p>Every project. Every owner. One living path forward.</p></div><div class="people-palette">${people.map(name=>`<label title="Set ${esc(name)} color"><input type="color" data-person-color="${esc(name)}" value="${colorHex(personColor(name))}"><span style="--person:${personColor(name)}">${esc(name)}</span></label>`).join('')}</div></div><div class="visual-board" id="visualBoard"><svg id="boardPaths" aria-hidden="true"><defs><filter id="pathGlow"><feGaussianBlur stdDeviation="2" result="blur"/><feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs><g></g></svg>${state.projects.map(project=>{if(project.server&&project.serverAccess===false)return `<section class="board-project board-locked"><div><p class="mono">PRIVATE PROJECT</p><h2>${esc(project.name)}</h2><span>SERVER ACCESS REQUIRED</span>${projectServer(project,true)}</div><b>⌁</b></section>`;const tasks=state.tasks.filter(t=>t.projectId===project.id);return `<section class="board-project" style="--accent:${project.accent||'#8b62ff'}"><header><div><p class="mono">${esc(project.stage||'PROJECT')} / ${tasks.length} TASKS</p><h2>${esc(project.name)}</h2></div>${projectServer(project,true)}<span>${esc(project.status||'Active')}</span></header><div class="postit-track">${tasks.map((task,index)=>`<article class="postit ${taskGlowClass(task.status)} ${['Completed','Approved'].includes(task.status)?'done':''}" data-board-task="${task.id}" data-task="${task.id}" style="--person:${personColor(task.assignee||'Unassigned')};--tilt:${index%2?'-1.2deg':'1deg'}"><small>${String(index+1).padStart(2,'0')} · ${esc(task.status)}</small><strong>${esc(task.title)}</strong><p>${esc(task.objective||'Open to define the next outcome.')}</p><footer><i></i>${esc(task.assignee||'Unassigned')}</footer></article>`).join('')||'<div class="board-empty">No tasks plotted yet.</div>'}</div></section>`}).join('')||'<div class="empty">Create a project to begin plotting the board.</div>'}</div></div>`}
function colorHex(color){if(/^#[0-9a-f]{6}$/i.test(color))return color;const match=String(color).match(/hsl\((\d+)/),h=Number(match?.[1]||260),s=.82,l=.68,c=(1-Math.abs(2*l-1))*s,x=c*(1-Math.abs((h/60)%2-1)),m=l-c/2;let [r,g,b]=h<60?[c,x,0]:h<120?[x,c,0]:h<180?[0,c,x]:h<240?[0,x,c]:h<300?[x,0,c]:[c,0,x];return '#'+[r,g,b].map(v=>Math.round((v+m)*255).toString(16).padStart(2,'0')).join('')}
function drawBoardPaths(){const board=$('#visualBoard'),svg=$('#boardPaths');if(!board||!svg)return;const root=board.getBoundingClientRect(),paths=[];board.querySelectorAll('.postit-track').forEach(track=>{const cards=[...track.querySelectorAll('.postit')];cards.slice(1).forEach((card,i)=>{const a=cards[i].getBoundingClientRect(),b=card.getBoundingClientRect(),x1=a.right-root.left,y1=a.top+a.height/2-root.top,x2=b.left-root.left,y2=b.top+b.height/2-root.top,curve=Math.max(30,(x2-x1)/2);paths.push(`<path d="M${x1},${y1} C${x1+curve},${y1} ${x2-curve},${y2} ${x2},${y2}"/>`)})});svg.setAttribute('viewBox',`0 0 ${board.scrollWidth} ${board.scrollHeight}`);svg.querySelector('g').innerHTML=paths.join('')}

function globalTaskRank(task){const rank=state.globalTaskOrder?.indexOf(task.id)??-1;return rank<0?Number.MAX_SAFE_INTEGER:rank}
function tasksView(){const completed=state.tasks.filter(t=>['Completed','Approved'].includes(t.status)),active=state.tasks.filter(t=>!['Completed','Approved'].includes(t.status)).sort((a,b)=>globalTaskRank(a)-globalTaskRank(b)),topTask=active[0],blocked=active.filter(t=>t.status==='Blocked').length,owners=[...new Set(active.map(t=>t.assignee?.trim()||'Unassigned'))];return `<div class="tasks-command"><div class="operations-heading"><div><p class="mono">TASK OPERATIONS / GLOBAL PRIORITY</p><h1>Execution queue.</h1><p>Drag tasks into one company-wide priority order, independent from every project's own plan.</p></div><button class="primary" id="quickTask">＋ NEW TASK</button></div><div class="task-operations-metrics"><article><b>${active.length}</b><span>ACTIVE</span></article><article><b>${owners.length}</b><span>OWNERS</span></article><article class="${blocked?'has-blockers':''}"><b>${blocked}</b><span>BLOCKED</span></article><article><b>${completed.length}</b><span>COMPLETED</span></article></div>${topTask?`<section class="global-now ${taskGlowClass(topTask.status)}" data-task="${topTask.id}"><div class="now-signal"><i></i><span>NEXT UP</span></div><div><small>TOP OF THE EXECUTION QUEUE · GLOBAL PRIORITY 01</small><h2>${esc(topTask.title)}</h2><p>${esc(state.projects.find(p=>p.id===topTask.projectId)?.name||'No project')} · ${esc(topTask.assignee||'Unassigned')}</p></div><span class="status ${statusClass(topTask.status)}">${esc(topTask.status)}</span><b>OPEN →</b></section>`:''}<div class="task-board"><section class="panel operations-list active-operations"><div class="panel-title"><div><p class="mono">ACTIVE QUEUE · GLOBAL PRIORITY</p><h3>NEEDS ACTION · DRAG TO REORDER</h3></div><small>${active.length} OPEN</small></div><div class="task-list global-task-list" id="globalTasks">${active.map((task,index)=>taskRow(task,index,false,true)).join('')||'<div class="empty operations-empty"><b>Nothing needs action</b><p>All tasks have been completed.</p></div>'}</div></section><section class="panel owner-workloads"><div class="panel-title"><div><p class="mono">RESPONSIBILITY MAP</p><h3>TASKS BY PERSON</h3></div><small>${owners.length} OWNERS</small></div><div class="owner-list">${owners.map(name=>{const tasks=active.filter(t=>(t.assignee?.trim()||'Unassigned')===name);return `<section class="owner-group" style="--person:${personColor(name)}"><header><span class="owner-avatar">${esc(name[0].toUpperCase())}</span><div><strong>${esc(name)}</strong><small>${tasks.length} ACTIVE TASK${tasks.length===1?'':'S'}</small></div></header>${tasks.map(task=>`<button class="${taskGlowClass(task.status)}" data-task="${task.id}"><i></i><span><strong>${esc(task.title)}</strong><small>#${String(active.indexOf(task)+1).padStart(2,'0')} · ${esc(state.projects.find(p=>p.id===task.projectId)?.name||'No project')}</small></span><em class="status ${statusClass(task.status)}">${esc(task.status)}</em></button>`).join('')}</section>`}).join('')||'<div class="empty">No active owners.</div>'}</div></section></div><section class="panel operations-list completed-operations"><div class="panel-title"><div><p class="mono">DELIVERED</p><h3>COMPLETED TASKS</h3></div><small>${completed.length} DONE</small></div><div class="task-list">${completed.map((task,index)=>taskRow(task,index,true)).join('')||'<div class="empty operations-empty"><b>No completed work yet</b></div>'}</div></section></div>`}
function databankView(){return `<input class="search" id="search" placeholder="Search confirmed answers, suppliers, decisions and keywords…"><div class="records" id="records">${recordsHtml(state.databank)}</div>`}
function recordsHtml(records){return records.map(r=>`<article class="record"><div class="project-top"><span class="mono">${esc(r.category)}</span><span class="status">${esc(r.reliability)}</span></div><h3>${esc(r.title)}</h3><p>${esc(r.answer)}</p><div class="tags">${r.keywords.map(k=>`<span class="tag">${esc(k)}</span>`).join('')}</div></article>`).join('')||'<div class="empty">No matching operational knowledge.</div>'}
function infoView(){return `<div class="info-command"><section class="info-heading"><div><p class="mono">SHARED DOCUMENTATION</p><h1>Knowledge, on file.</h1><p>PDF references are securely backed up in the private Bridge and available to every connected member.</p></div><button class="primary" id="addDocument">＋ UPLOAD PDF</button></section><div class="document-stats"><span><b>${state.documentation.length}</b> DOCUMENT${state.documentation.length===1?'':'S'} AVAILABLE</span><span>PRIVATE BRIDGE BACKUP</span></div><div class="document-grid">${state.documentation.map(documentCard).join('')||'<section class="document-empty"><div>ⓘ</div><h2>Your documentation library is empty.</h2><p>Upload a PDF and give it a clear title to make it available here.</p><button class="ghost" id="emptyAddDocument">UPLOAD FIRST DOCUMENT</button></section>'}</div></div>`}
function documentCard(document){const size=document.size?`${(document.size/1024/1024).toFixed(document.size>=1024*1024?1:2)} MB`:'PDF';return `<article class="document-card"><div class="pdf-mark"><b>PDF</b><span>◰</span></div><div class="document-copy"><span class="mono">DOCUMENTATION / ${esc(size)}</span><h2>${esc(document.title)}</h2><p>${esc(document.fileName||'Bridge document')} · Added ${new Date(document.createdAt).toLocaleDateString()} by ${esc(document.createdBy||'Unknown')}</p></div><div class="document-actions"><button class="primary" data-open-document="${document.id}">READ ON PAGE →</button><button class="danger-button" data-delete-document="${document.id}">DELETE</button></div></article>`}
function documentationDialog(){showModal(`<form id="documentationForm" class="modal-content"><p class="mono">ADD TO INFO LIBRARY</p><h2>Upload documentation</h2><p class="modal-intro">Choose a descriptive title, then select a PDF (maximum 20 MB). The file will be committed to the private Bridge repository.</p><div class="form-grid"><label class="wide">DOCUMENT TITLE<input class="form-input" name="title" required maxlength="140" placeholder="e.g. Partner onboarding guide"></label><button class="primary wide">CHOOSE PDF &amp; UPLOAD</button></div></form>`);$('#documentationForm').onsubmit=async event=>{event.preventDefault();const button=event.submitter,title=new FormData(event.target).get('title').trim(),id=uid('document');button.disabled=true;button.textContent='UPLOADING TO BRIDGE…';try{const uploaded=await window.crowdnet.uploadDocumentation({id,title});if(uploaded.canceled){button.disabled=false;button.textContent='CHOOSE PDF & UPLOAD';return}const item={id,title,...uploaded,createdAt:now(),createdBy:user};state.documentation.unshift(item);meta(item);activity('documentation',`${title} added`,'PDF backed up to the Bridge',id);$('#modal').close();render();queueSave('add documentation');toast('Documentation uploaded and backed up to the Bridge.')}catch(error){button.disabled=false;button.textContent='CHOOSE PDF & UPLOAD';toast(`Upload failed: ${error.message}`)}}}
async function openDocument(id){const document=state.documentation.find(item=>item.id===id);if(!document)return;const viewer=$('#documentViewer'),frame=$('#pdfFrame');$('#viewerTitle').textContent=document.title;$('#viewerStatus').textContent='LOADING FROM BRIDGE';viewer.classList.remove('ready');viewer.classList.add('open');viewer.setAttribute('aria-hidden','false');try{const file=await window.crowdnet.prepareDocumentation({id:document.id});frame.src=file.url;frame.onload=()=>{viewer.classList.add('ready');$('#viewerStatus').textContent='SECURE · BRIDGE BACKED'}}catch(error){closeDocumentViewer();toast(`Could not display PDF: ${error.message}`)}}
function closeDocumentViewer(){const viewer=$('#documentViewer'),frame=$('#pdfFrame');viewer.classList.remove('open','ready');viewer.setAttribute('aria-hidden','true');frame.removeAttribute('src');frame.onload=null}
$('#closeViewer').onclick=closeDocumentViewer;$('#documentViewer .viewer-scrim').onclick=closeDocumentViewer;addEventListener('keydown',event=>{if(event.key==='Escape'&&$('#documentViewer').classList.contains('open'))closeDocumentViewer()});
async function deleteDocument(id){const document=state.documentation.find(item=>item.id===id);if(!document||!confirm(`Delete “${document.title}” from the Info library and Bridge?`))return;try{await window.crowdnet.deleteDocumentation({id:document.id,title:document.title,sha:document.sha});state.documentation=state.documentation.filter(item=>item.id!==id);state.revision++;state.updatedAt=now();activity('documentation',`${document.title} deleted`,'PDF removed from the Bridge',id);render();queueSave('delete documentation');toast('Documentation deleted.')}catch(error){toast(`Delete failed: ${error.message}`)}}
function peopleView(){return `<div class="people-grid">${state.people.map(p=>{const assigned=state.tasks.filter(t=>t.assignee===p.name),active=assigned.filter(t=>!['Completed','Archived'].includes(t.status));return `<article class="panel person"><div class="big-avatar">${esc(p.name[0])}</div><span class="mono">${p.external?'EXTERNAL RESPONSIBILITY':'CROWDNET MEMBER'}</span><h2>${esc(p.name)}</h2><p>${esc(p.role)}</p><div class="metrics"><div class="metric"><b>${active.length}</b><span>ACTIVE</span></div><div class="metric"><b>${assigned.filter(t=>t.status==='Completed').length}</b><span>DONE</span></div></div></article>`}).join('')||'<div class="empty">No people have been added to this workspace.</div>'}</div>`}
function bindContent(){if(view==='board'){requestAnimationFrame(drawBoardPaths);document.querySelectorAll('[data-person-color]').forEach(input=>input.oninput=()=>{state.personColors||={};state.personColors[input.dataset.personColor]=input.value;render();queueSave('update board person colors')})}$('#addDocument')?.addEventListener('click',documentationDialog);$('#emptyAddDocument')?.addEventListener('click',documentationDialog);document.querySelectorAll('[data-open-document]').forEach(el=>el.onclick=()=>openDocument(el.dataset.openDocument));document.querySelectorAll('[data-delete-document]').forEach(el=>el.onclick=()=>deleteDocument(el.dataset.deleteDocument));document.querySelectorAll('[data-project]').forEach(el=>el.onclick=()=>{selectedProjectId=el.dataset.project;view='projects';render()});document.querySelectorAll('[data-task]').forEach(el=>el.onclick=()=>{selectedTaskId=el.dataset.task;view='tasks';render()});document.querySelectorAll('[data-edit-project]').forEach(el=>el.onclick=event=>{event.stopPropagation();projectDialog(el.dataset.editProject)});document.querySelectorAll('[data-delete-project]').forEach(el=>el.onclick=event=>{event.stopPropagation();deleteProject(el.dataset.deleteProject)});document.querySelectorAll('[data-edit-task]').forEach(el=>el.onclick=event=>{event.stopPropagation();taskDialog(el.dataset.editTask)});document.querySelectorAll('[data-delete-task]').forEach(el=>el.onclick=event=>{event.stopPropagation();deleteTask(el.dataset.deleteTask)});$('#quickTask')?.addEventListener('click',()=>taskDialog());$('#projectNewTask')?.addEventListener('click',()=>taskDialog(null,selectedProjectId));$('#emptyNewTask')?.addEventListener('click',()=>taskDialog(null,selectedProjectId));$('#backProjects')?.addEventListener('click',()=>{selectedProjectId=null;render()});$('#backTasks')?.addEventListener('click',()=>{selectedTaskId=null;render()});$('#advanceTask')?.addEventListener('click',advanceSelectedTask);$('#syncGithub')?.addEventListener('click',()=>autoMatchProject(state.projects.find(p=>p.id===selectedProjectId),true));$('#search')?.addEventListener('input',event=>{const q=event.target.value.toLowerCase();$('#records').innerHTML=recordsHtml(state.databank.filter(r=>JSON.stringify(r).toLowerCase().includes(q)))});bindTaskReorder();bindGlobalTaskReorder();const project=state.projects.find(p=>p.id===selectedProjectId);if(project&&!selectedTaskId)autoMatchProject(project)}
function bindGlobalTaskReorder(){const list=$('#globalTasks');if(!list)return;let dragged;const commit=()=>{state.globalTaskOrder=[...list.querySelectorAll('.operation-task')].map(row=>row.dataset.task);state.revision++;state.updatedAt=now();activity('task','Global priority updated','Company-wide execution queue reprioritized','global-tasks');render();queueSave('reorder global task priority')};list.querySelectorAll('.operation-task').forEach(row=>{row.addEventListener('dragstart',event=>{dragged=row;row.classList.add('dragging');event.dataTransfer.effectAllowed='move'});row.addEventListener('dragend',()=>{row.classList.remove('dragging');dragged=null});row.addEventListener('dragover',event=>{event.preventDefault();if(!dragged||dragged===row)return;const after=event.clientY>row.getBoundingClientRect().top+row.offsetHeight/2;list.insertBefore(dragged,after?row.nextSibling:row)});row.addEventListener('drop',event=>{event.preventDefault();event.stopPropagation();commit()})})}

function bindTaskReorder(){const list=$('#projectTasks');if(!list)return;let dragged;list.querySelectorAll('.project-task').forEach(row=>{row.addEventListener('dragstart',()=>{dragged=row;row.classList.add('dragging')});row.addEventListener('dragend',()=>{row.classList.remove('dragging');dragged=null});row.addEventListener('dragover',event=>{event.preventDefault();if(!dragged||dragged===row)return;const after=event.clientY>row.getBoundingClientRect().top+row.offsetHeight/2;list.insertBefore(dragged,after?row.nextSibling:row)});row.addEventListener('drop',event=>{event.preventDefault();const ids=[...list.querySelectorAll('.project-task')].map(el=>el.dataset.task),ordered=ids.map(id=>state.tasks.find(t=>t.id===id)),others=state.tasks.filter(t=>t.projectId!==selectedProjectId||['Completed','Approved'].includes(t.status));state.tasks=[...others,...ordered];state.revision++;state.updatedAt=now();activity('task','Task order updated','Execution plan reprioritized',selectedProjectId);render();queueSave('reorder project tasks')})})}

function deleteProject(id){const project=state.projects.find(item=>item.id===id);if(!project||!confirm(`Delete “${project.name}”, all of its tasks, and their Databank records?`))return;const taskIds=new Set(state.tasks.filter(task=>task.projectId===id).map(task=>task.id));state.projects=state.projects.filter(item=>item.id!==id);state.tasks=state.tasks.filter(task=>!taskIds.has(task.id));state.databank=state.databank.filter(record=>record.projectId!==id&&!taskIds.has(record.taskId));activity('project',`${project.name} deleted`,`${taskIds.size} related task${taskIds.size===1?'':'s'} and their knowledge removed`,id);state.revision++;state.updatedAt=now();render();queueSave('delete project')}
function deleteTask(id){const task=state.tasks.find(item=>item.id===id);if(!task||!confirm(`Delete task “${task.title}” and its Databank record?`))return;state.tasks=state.tasks.filter(item=>item.id!==id);state.databank=state.databank.filter(record=>record.taskId!==id);activity('task',`${task.title} deleted`,'Task and linked Databank knowledge removed',id);state.revision++;state.updatedAt=now();selectedTaskId=null;render();queueSave('delete task')}

function showModal(html){$('#modalBody').innerHTML=html;$('#modal').showModal()}
function projectDialog(id){const p=state.projects.find(x=>x.id===id);showModal(`<form id="projectForm" class="modal-content"><p class="mono">${p?'PROJECT DEVELOPMENT VIEW':'CREATE PROJECT'}</p><h2>${p?esc(p.name):'New project'}</h2><div class="form-grid"><label>NAME<input class="form-input" name="name" required value="${esc(p?.name||'')}"></label><label>STAGE<select class="form-input" name="stage">${['Idea','Research','Validation','Development','Launch','Growth'].map(x=>`<option ${p?.stage===x?'selected':''}>${x}</option>`)}</select></label><label>SERVER<select class="form-input" name="server"><option value="">CROWDNET PRIMARY SERVER</option>${availableServers.map(server=>`<option value="${esc(server.id)}" ${(p?.server||'')===server.id?'selected':''}>${esc(server.name)}</option>`).join('')}</select></label><label class="wide">DESCRIPTION<textarea name="description">${esc(p?.description||'')}</textarea></label><label>PRIORITY<select class="form-input" name="priority">${['Critical','High','Medium','Low'].map(x=>`<option ${p?.priority===x?'selected':''}>${x}</option>`)}</select></label><label>PROGRESS<input class="form-input" name="progress" type="number" min="0" max="100" value="${p?.progress||0}"></label><label>CURRENT OBJECTIVE<input class="form-input" name="objective" value="${esc(p?.objective||'')}"></label><label>NEXT ACTION<input class="form-input" name="nextAction" value="${esc(p?.nextAction||'')}"></label><button class="primary wide">${p?'SAVE PROJECT':'CREATE PROJECT'}</button></div></form>`);$('#projectForm').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(p){const oldStage=p.stage;Object.assign(p,data,{server:data.server||'',serverAccess:true,progress:Number(data.progress)});meta(p);if(oldStage!==p.stage)activity('project',`${p.name} advanced`,`${oldStage} → ${p.stage}`,p.id)}else{const item={id:uid('project'),...data,server:data.server||'',serverAccess:true,progress:Number(data.progress),status:'Active',accent:Math.random()>.5?'#8b62ff':'#43d9ff',members:[user]};meta(item,true);state.projects.push(item);activity('project',`${item.name} created`,'A new project entered the network',item.id)}$('#modal').close();render();queueSave(p?'update project':'create project')}}
function taskDialog(id,projectId=selectedProjectId){const t=state.tasks.find(x=>x.id===id);if(!t&&!state.projects.length){toast('Create a project before adding tasks.');return}showModal(`<form id="taskForm" class="modal-content"><p class="mono">${t?'TASK / '+esc(t.id):'CREATE TASK WORKSPACE'}</p><h2>${t?esc(t.title):'New assignment'}</h2><div class="form-grid"><label class="wide">TITLE<input class="form-input" name="title" required value="${esc(t?.title||'')}"></label><label>PROJECT<select class="form-input" name="projectId">${state.projects.map(p=>`<option value="${p.id}" ${(t?.projectId||projectId)===p.id?'selected':''}>${esc(p.name)}</option>`)}</select></label><label>ASSIGNEE<input class="form-input" name="assignee" value="${esc(t?.assignee||user)}"></label><label>STATUS<select class="form-input" name="status">${statuses.map(x=>`<option ${t?.status===x?'selected':''}>${x}</option>`)}</select></label><label>PRIORITY<select class="form-input" name="priority">${['Critical','High','Medium','Low'].map(x=>`<option ${t?.priority===x?'selected':''}>${x}</option>`)}</select></label><label class="wide">OBJECTIVE<textarea name="objective">${esc(t?.objective||'')}</textarea></label><label class="wide">INSTRUCTIONS<textarea name="instructions">${esc(t?.instructions||'')}</textarea></label><label class="wide">NOTES & RESEARCH<textarea name="notes">${esc(t?.notes||'')}</textarea></label><label class="wide">DRAFT ANSWER<textarea name="draftAnswer">${esc(t?.draftAnswer||'')}</textarea></label><label class="wide">FINAL CONFIRMED RESULT<textarea name="finalResult">${esc(t?.finalResult||'')}</textarea></label><label class="wide">REVIEW COMMENTS<textarea name="reviewComments">${esc(t?.reviewComments||'')}</textarea></label><button class="primary wide">SAVE TASK &amp; WORK</button></div></form>`);$('#taskForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter,data=Object.fromEntries(new FormData(e.target)),oldStatus=t?.status,snapshot=t?{...t}:null,item=t||{id:uid('task'),...data,creator:user};button.disabled=true;if(t)Object.assign(t,data);try{await updateIssueForTask(item)}catch(error){if(t)Object.assign(t,snapshot);toast(`Task was not saved: ${error.message}`);button.disabled=false;return}meta(item,t?false:true);if(!t){state.tasks.push(item);activity('task',`${item.title} created`,`Server issue #${item.githubIssueNumber} · assigned to ${item.assignee}`,item.id)}if(oldStatus&&oldStatus!==item.status)activity('status',`${item.title}: ${item.status}`,`${oldStatus} → ${item.status}`,item.id);if(ensureDatabankRecord(item))toast('Completed task · server issue closed · Databank record confirmed');$('#modal').close();render();queueSave('update task workspace and server issue')}}

// Lightweight, visibility-aware space field.
const canvas=$('#space'),ctx=canvas.getContext('2d');let stars=[];function resize(){canvas.width=innerWidth;canvas.height=innerHeight;stars=Array.from({length:60},()=>[Math.random()*innerWidth,Math.random()*innerHeight,Math.random()+.2])}function draw(){if(!document.hidden){ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#7382ad';stars.forEach(s=>{s[1]=(s[1]+s[2]*.04)%innerHeight;ctx.globalAlpha=s[2]*.25;ctx.fillRect(s[0],s[1],s[2],s[2])})}requestAnimationFrame(draw)}addEventListener('resize',resize);resize();draw();
